/**
 * Pure-logic state mutator for the procedural room.
 *
 * Given the spec + a twin's new state, returns a new spec with the
 * matching primitive's transform / material updated. The renderer
 * adapter consumes the diff between old + new primitive specs to
 * tween the Three.js object property in real time (no full scene
 * rebuild per state change).
 *
 * Pure logic so visitor toggles can be tested without Three.js.
 */

import {
  findPrimitiveForTwin,
  type PrimitiveSpec,
  type ProceduralRoomSpec,
} from './procedural-room-spec';

import type { TwinState } from '@nova/digital-twin';

/** Apply a twin state change to the spec — returns a new spec with the
 *  one matching primitive updated. */
export function applyTwinStateToSpec(
  spec: ProceduralRoomSpec,
  twinId: string,
  next: TwinState,
): ProceduralRoomSpec {
  const target = findPrimitiveForTwin(spec, twinId);
  if (!target) return spec;
  const updated = mutatePrimitive(target, next);
  if (updated === target) return spec;
  return {
    ...spec,
    primitives: spec.primitives.map((p) => (p.id === target.id ? updated : p)),
  };
}

function mutatePrimitive(prim: PrimitiveSpec, state: TwinState): PrimitiveSpec {
  switch (state.kind) {
    case 'lamp':
      return {
        ...prim,
        emissive: state.state.on
          ? [
              1 * (state.state.brightness ?? 1),
              0.85 * (state.state.brightness ?? 1),
              0.55 * (state.state.brightness ?? 1),
            ]
          : [0, 0, 0],
      };
    case 'door': {
      const openAngle = state.state.open ? -90 : 0;
      return {
        ...prim,
        rotationDeg: [prim.rotationDeg?.[0] ?? 0, openAngle, prim.rotationDeg?.[2] ?? 0],
      };
    }
    case 'shade': {
      // position 0 = fully open, 1 = fully closed
      const closedness = state.state.position;
      return {
        ...prim,
        scale: [closedness, 1, 1],
        opacity: closedness > 0 ? 0.92 : 0.0,
      };
    }
    case 'media-display':
      return {
        ...prim,
        color: state.state.playing ? [0.08, 0.16, 0.32] : [0.05, 0.05, 0.05],
        emissive: state.state.playing ? [0.18, 0.36, 0.78] : [0, 0, 0],
      };
    default:
      return prim;
  }
}
