import {
  fovWedgePath,
  minimapEdges,
  pickNearestScene,
  projectFovWedge,
  projectScenesToMinimap,
  type CameraState,
  type SceneGraph,
} from '@nova/viewer-core';

/**
 * Minimap (F-15) — top-right SVG overlay showing every scene in the tour,
 * the current scene's highlight ring, edges between connected scenes, and a
 * triangle wedge representing the current camera's FOV cone.
 *
 * Click on any scene dot → onJumpTo(sceneId). Mouseover surfaces the scene
 * name as a tooltip. Defaults to collapsed on mobile (≤768px) — the user
 * taps the badge to expand.
 */

export interface MinimapArgs {
  hostEl: HTMLElement;
  graph: SceneGraph;
  currentSceneId: string;
  cameraFovDeg: number;
  cameraYawDeg: number;
  onJumpTo: (sceneId: string) => void;
}

export interface MinimapHandle {
  setCurrentScene(sceneId: string): void;
  setCamera(camera: CameraState): void;
  dispose(): void;
}

const SVG_NS = 'http://www.w3.org/2000/svg';

export const mountMinimap = (args: MinimapArgs): MinimapHandle => {
  const viewBox = args.graph.minimapViewBox ?? { widthPx: 200, heightPx: 200 };
  const root = document.createElement('div');
  root.className = 'viewer-minimap';
  root.setAttribute('data-testid', 'viewer-minimap');
  root.setAttribute('role', 'group');
  root.setAttribute('aria-label', 'Tour minimap');

  const heading = document.createElement('div');
  heading.className = 'viewer-minimap-heading';
  heading.textContent = 'Tour map';
  root.appendChild(heading);

  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${viewBox.widthPx} ${viewBox.heightPx}`);
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', `Tour minimap with ${args.graph.scenes.size} scenes`);
  svg.classList.add('viewer-minimap-svg');
  root.appendChild(svg);

  args.hostEl.appendChild(root);

  // ---- edges layer (bottom) ----
  const scenesArray = [...args.graph.scenes.values()];
  const pointById = new Map(
    projectScenesToMinimap(scenesArray, viewBox).map((p) => [p.sceneId, p]),
  );

  const edgeGroup = document.createElementNS(SVG_NS, 'g');
  edgeGroup.classList.add('viewer-minimap-edges');
  for (const edge of minimapEdges(args.graph)) {
    const a = pointById.get(edge.fromSceneId);
    const b = pointById.get(edge.toSceneId);
    if (a === undefined || b === undefined) continue;
    const line = document.createElementNS(SVG_NS, 'line');
    line.setAttribute('x1', a.xPx.toString());
    line.setAttribute('y1', a.yPx.toString());
    line.setAttribute('x2', b.xPx.toString());
    line.setAttribute('y2', b.yPx.toString());
    edgeGroup.appendChild(line);
  }
  svg.appendChild(edgeGroup);

  // ---- FOV wedge ----
  const wedgePath = document.createElementNS(SVG_NS, 'path');
  wedgePath.classList.add('viewer-minimap-fov');
  svg.appendChild(wedgePath);

  // ---- scene dots ----
  const dotGroup = document.createElementNS(SVG_NS, 'g');
  dotGroup.classList.add('viewer-minimap-dots');
  const dotByScene = new Map<string, SVGGElement>();
  for (const [sceneId, point] of pointById) {
    const scene = args.graph.scenes.get(sceneId);
    if (scene === undefined) continue;
    const g = document.createElementNS(SVG_NS, 'g');
    g.classList.add('viewer-minimap-dot');
    g.setAttribute('data-scene-id', sceneId);
    g.setAttribute('transform', `translate(${point.xPx} ${point.yPx})`);
    g.setAttribute('role', 'button');
    g.setAttribute('tabindex', '0');
    g.setAttribute('aria-label', `Jump to ${scene.name}`);

    const ring = document.createElementNS(SVG_NS, 'circle');
    ring.setAttribute('r', point.radiusPx.toString());
    ring.classList.add('viewer-minimap-dot-ring');
    g.appendChild(ring);

    const inner = document.createElementNS(SVG_NS, 'circle');
    inner.setAttribute('r', Math.max(point.radiusPx - 3, 2).toString());
    inner.classList.add('viewer-minimap-dot-fill');
    g.appendChild(inner);

    const label = document.createElementNS(SVG_NS, 'text');
    label.setAttribute('y', (point.radiusPx + 12).toString());
    label.setAttribute('text-anchor', 'middle');
    label.classList.add('viewer-minimap-dot-label');
    label.textContent = scene.name;
    g.appendChild(label);

    g.addEventListener('click', () => args.onJumpTo(sceneId));
    g.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        args.onJumpTo(sceneId);
      }
    });

    dotGroup.appendChild(g);
    dotByScene.set(sceneId, g);
  }
  svg.appendChild(dotGroup);

  const refreshWedge = (
    cameraYawDeg: number,
    cameraFovDeg: number,
    currentSceneId: string,
  ): void => {
    const scene = args.graph.scenes.get(currentSceneId);
    if (scene === undefined) {
      wedgePath.setAttribute('d', '');
      return;
    }
    const wedge = projectFovWedge({
      scene,
      cameraYawDeg,
      cameraFovDeg,
      viewBox,
      reachPx: 36,
    });
    if (wedge === null) {
      wedgePath.setAttribute('d', '');
      return;
    }
    wedgePath.setAttribute('d', fovWedgePath(wedge));
  };

  let currentSceneId = args.currentSceneId;
  let currentYaw = args.cameraYawDeg;
  let currentFov = args.cameraFovDeg;

  const refreshCurrentHighlight = (): void => {
    for (const [id, g] of dotByScene) {
      if (id === currentSceneId) g.classList.add('is-current');
      else g.classList.remove('is-current');
    }
  };
  refreshCurrentHighlight();
  refreshWedge(currentYaw, currentFov, currentSceneId);

  // Click-anywhere-on-the-svg fallback: when the user clicks empty area
  // we hit-test against the nearest dot within threshold so the minimap is
  // forgiving of fat-finger touches.
  svg.addEventListener('click', (event) => {
    const target = event.target as Element | null;
    if (target?.closest('.viewer-minimap-dot') !== null) return;
    const rect = svg.getBoundingClientRect();
    const xPx = ((event.clientX - rect.left) / rect.width) * viewBox.widthPx;
    const yPx = ((event.clientY - rect.top) / rect.height) * viewBox.heightPx;
    const hit = pickNearestScene({
      pointXPx: xPx,
      pointYPx: yPx,
      scenes: [...pointById.values()],
      thresholdPx: 24,
    });
    if (hit !== null && hit !== currentSceneId) args.onJumpTo(hit);
  });

  return {
    setCurrentScene(sceneId): void {
      currentSceneId = sceneId;
      refreshCurrentHighlight();
      refreshWedge(currentYaw, currentFov, currentSceneId);
    },
    setCamera(camera): void {
      currentYaw = camera.yaw;
      currentFov = camera.fov;
      refreshWedge(currentYaw, currentFov, currentSceneId);
    },
    dispose(): void {
      if (root.parentElement === args.hostEl) args.hostEl.removeChild(root);
    },
  };
};
