/**
 * Free-roam 3D renderer (BETA) — walk the actual villa model in real time, the
 * "free walk" Matterport-style experience (the cd.xyz reference the owner liked
 * is a Matterport embed). Loads the decimated villa GLB (322MB → ~46MB via
 * gltf-transform: 2K WebP + meshopt) and lights it with image-based lighting +
 * a sun + ACES tone-mapping so it reads close to the baked 360 panoramas.
 *
 * Navigation = Matterport's model: DRAG to look, CLICK/TAP the floor to glide
 * there, CLICK an object to inspect it. WASD also moves (desktop). The camera
 * follows the floor (raycast-down) at eye height and won't walk through walls.
 *
 * This is intentionally a SEPARATE renderer from the panorama path — the
 * photoreal 360 tour stays the default; free-roam is an opt-in `?freeroam=1`.
 */

import {
  ACESFilmicToneMapping,
  Box3,
  DirectionalLight,
  HemisphereLight,
  MathUtils,
  type Mesh,
  type Object3D,
  PerspectiveCamera,
  PMREMGenerator,
  Raycaster,
  Scene,
  SRGBColorSpace,
  Vector2,
  Vector3,
  WebGLRenderer,
} from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';

export interface FreeroamArgs {
  mountEl: HTMLElement;
  modelUrl: string;
  /** Approx world spawn point (glTF Y-up). The camera floor-snaps from here. */
  spawn?: { x: number; y: number; z: number };
  onProgress?: (progress01: number) => void;
  onReady?: () => void;
  /** Fired when the visitor clicks a non-floor object (label = mesh name). */
  onPick?: (label: string) => void;
}

export interface FreeroamHandle {
  dispose(): void;
}

const EYE = 1.65; // metres above the floor
const MOVE_SPEED = 3.2; // m/s (WASD)
const GLIDE_MS = 650; // click-to-move travel time

const easeInOut = (t: number): number => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

export const mountFreeroam = async (args: FreeroamArgs): Promise<FreeroamHandle> => {
  const renderer = new WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.outputColorSpace = SRGBColorSpace;
  const sizeTo = (): void => {
    const w = Math.max(args.mountEl.clientWidth, 320);
    const h = Math.max(args.mountEl.clientHeight, 240);
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  };
  args.mountEl.appendChild(renderer.domElement);
  renderer.domElement.style.touchAction = 'none';

  const scene = new Scene();
  const camera = new PerspectiveCamera(72, 1, 0.05, 2000);

  // ── Lighting: IBL (soft ambient) + a warm sun + sky/ground fill ──────────
  const pmrem = new PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  const sun = new DirectionalLight(0xfff2e0, 2.6);
  sun.position.set(60, 120, 40);
  scene.add(sun);
  scene.add(new HemisphereLight(0xbfd4ff, 0x6b5d4f, 0.55));

  // ── Load the villa ───────────────────────────────────────────────────────
  const loader = new GLTFLoader();
  loader.setMeshoptDecoder(MeshoptDecoder);
  const gltf = await new Promise<{ scene: Object3D }>((resolve, reject) => {
    loader.load(
      args.modelUrl,
      (g) => resolve(g),
      (e) => {
        if (e.lengthComputable && e.total > 0) args.onProgress?.(e.loaded / e.total);
      },
      (err) => reject(err instanceof Error ? err : new Error(String(err))),
    );
  });
  const villa = gltf.scene;
  scene.add(villa);

  // If the export kept Blender's Z-up, rotate to three's Y-up (detected when the
  // vertical extent — building height — is the smallest axis along Z).
  {
    const s = new Box3().setFromObject(villa).getSize(new Vector3());
    if (s.z < s.y * 0.8 && s.z < s.x * 0.8) {
      villa.rotation.x = -Math.PI / 2;
      villa.updateMatrixWorld(true);
    }
  }

  // Collidable / pickable meshes.
  const meshes: Mesh[] = [];
  villa.traverse((o) => {
    if ((o as Mesh).isMesh) meshes.push(o as Mesh);
  });

  const bbox = new Box3().setFromObject(villa);
  const center = bbox.getCenter(new Vector3());

  // ── Camera orientation state ──────────────────────────────────────────────
  let yaw = Math.PI; // radians
  let pitch = 0;
  const downRay = new Raycaster();
  const pickRay = new Raycaster();
  const tmp = new Vector3();

  /** First floor below `fromY` at (x,z), ignoring anything above. */
  const floorYAt = (x: number, z: number, fromY: number): number | null => {
    downRay.set(new Vector3(x, fromY, z), new Vector3(0, -1, 0));
    const hits = downRay.intersectObjects(meshes, false);
    const floor = hits.find((h) => h.point.y < fromY - 0.1);
    return floor ? floor.point.y : null;
  };

  // Auto-find an INTERIOR spawn: sample a grid over the footprint and pick a
  // floor that has a ceiling 2–4.5 m above it (a real room), nearest the centre.
  // Robust to the GLB's coordinate convention + the surrounding garden.
  const findInteriorSpawn = (): Vector3 => {
    const N = 9;
    let best: Vector3 | null = null;
    let bestScore = -Infinity;
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        const x = bbox.min.x + ((bbox.max.x - bbox.min.x) * (i + 0.5)) / N;
        const z = bbox.min.z + ((bbox.max.z - bbox.min.z) * (j + 0.5)) / N;
        downRay.set(new Vector3(x, bbox.max.y + 5, z), new Vector3(0, -1, 0));
        const hits = downRay.intersectObjects(meshes, false);
        for (let k = hits.length - 1; k >= 1; k--) {
          const floorY = hits[k]!.point.y;
          const headroom = hits[k - 1]!.point.y - floorY;
          if (headroom > 1.9 && headroom < 4.5) {
            const dist = Math.hypot(x - center.x, z - center.z);
            const score = -dist;
            if (score > bestScore) {
              bestScore = score;
              best = new Vector3(x, floorY + EYE, z);
            }
            break;
          }
        }
      }
    }
    return best ?? new Vector3(center.x, (bbox.min.y + bbox.max.y) / 2, center.z);
  };
  camera.position.copy(findInteriorSpawn());

  // Face the most OPEN direction from the spawn (best first impression — don't
  // open the experience staring into a cabinet/wall).
  {
    let bestDist = -1;
    for (let a = 0; a < 16; a++) {
      const ang = (a / 16) * Math.PI * 2;
      pickRay.set(camera.position, new Vector3(Math.sin(ang), 0, Math.cos(ang)));
      const h = pickRay.intersectObjects(meshes, false)[0];
      const d = h ? h.distance : 999;
      if (d > bestDist) {
        bestDist = d;
        yaw = ang;
      }
    }
  }

  const applyLook = (): void => {
    pitch = MathUtils.clamp(pitch, -Math.PI / 2 + 0.05, Math.PI / 2 - 0.05);
    const dir = new Vector3(
      Math.sin(yaw) * Math.cos(pitch),
      Math.sin(pitch),
      Math.cos(yaw) * Math.cos(pitch),
    );
    camera.lookAt(tmp.copy(camera.position).add(dir));
  };
  applyLook();

  // ── Input: drag-look + click-to-move + object pick ────────────────────────
  let dragging = false;
  let moved = false;
  let lastX = 0;
  let lastY = 0;
  let downX = 0;
  let downY = 0;

  const onDown = (e: PointerEvent): void => {
    dragging = true;
    moved = false;
    lastX = downX = e.clientX;
    lastY = downY = e.clientY;
    renderer.domElement.setPointerCapture(e.pointerId);
  };
  const onMove = (e: PointerEvent): void => {
    if (!dragging) return;
    const dx = e.clientX - lastX;
    const dy = e.clientY - lastY;
    lastX = e.clientX;
    lastY = e.clientY;
    if (Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY) > 6) moved = true;
    yaw -= dx * 0.0042;
    pitch -= dy * 0.0042;
    applyLook();
  };
  const onUp = (e: PointerEvent): void => {
    dragging = false;
    try {
      renderer.domElement.releasePointerCapture(e.pointerId);
    } catch {
      /* ignore */
    }
    if (moved) return; // it was a look-drag, not a click
    handleClick(e.clientX, e.clientY);
  };

  const handleClick = (clientX: number, clientY: number): void => {
    const rect = renderer.domElement.getBoundingClientRect();
    const ndc = new Vector2(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1,
    );
    pickRay.setFromCamera(ndc, camera);
    const hits = pickRay.intersectObjects(meshes, false);
    if (hits.length === 0) return;
    const hit = hits[0]!;
    const n = hit.face?.normal;
    const walkable = n ? n.y > 0.5 : false;
    const belowEye = hit.point.y < camera.position.y - 0.3;
    if (walkable && belowEye) {
      glideTo(hit.point.x, hit.point.z);
    } else {
      const name = hit.object.name || 'Object';
      args.onPick?.(prettify(name));
    }
  };

  // Click-to-move glide (Matterport-style).
  let glide: { fromX: number; fromZ: number; toX: number; toZ: number; t0: number } | null = null;
  const glideTo = (x: number, z: number): void => {
    // Don't walk past a wall between here and there.
    const from = new Vector2(camera.position.x, camera.position.z);
    const to = new Vector2(x, z);
    const dist = from.distanceTo(to);
    if (dist > 0.2) {
      pickRay.set(
        new Vector3(camera.position.x, camera.position.y - 0.4, camera.position.z),
        new Vector3((x - camera.position.x) / dist, 0, (z - camera.position.z) / dist),
      );
      const wall = pickRay.intersectObjects(meshes, false).find((h) => h.distance < dist - 0.3);
      if (wall) {
        const stop = Math.max(0, wall.distance - 0.4);
        x = camera.position.x + ((x - camera.position.x) / dist) * stop;
        z = camera.position.z + ((z - camera.position.z) / dist) * stop;
      }
    }
    glide = { fromX: camera.position.x, fromZ: camera.position.z, toX: x, toZ: z, t0: performance.now() };
  };

  renderer.domElement.addEventListener('pointerdown', onDown);
  renderer.domElement.addEventListener('pointermove', onMove);
  renderer.domElement.addEventListener('pointerup', onUp);
  renderer.domElement.addEventListener('pointercancel', onUp);

  // WASD (desktop).
  const keys = new Set<string>();
  const onKeyDown = (e: KeyboardEvent): void => {
    keys.add(e.key.toLowerCase());
  };
  const onKeyUp = (e: KeyboardEvent): void => {
    keys.delete(e.key.toLowerCase());
  };
  window.addEventListener('keydown', onKeyDown);
  window.addEventListener('keyup', onKeyUp);

  const moveBy = (forward: number, strafe: number): void => {
    const fx = Math.sin(yaw);
    const fz = Math.cos(yaw);
    const nx = camera.position.x + (fx * forward + fz * strafe);
    const nz = camera.position.z + (fz * forward - fx * strafe);
    // Wall check.
    const dir = new Vector3(nx - camera.position.x, 0, nz - camera.position.z);
    const len = dir.length();
    if (len > 0.001) {
      pickRay.set(new Vector3(camera.position.x, camera.position.y - 0.4, camera.position.z), dir.clone().normalize());
      const wall = pickRay.intersectObjects(meshes, false).find((h) => h.distance < len + 0.35);
      if (wall) return;
    }
    camera.position.x = nx;
    camera.position.z = nz;
  };

  // ── Render loop ────────────────────────────────────────────────────────────
  const resizeObs = new ResizeObserver(sizeTo);
  resizeObs.observe(args.mountEl);
  sizeTo();

  let stopped = false;
  let prev = performance.now();
  const loop = (): void => {
    if (stopped) return;
    const now = performance.now();
    const dt = Math.min(0.05, (now - prev) / 1000);
    prev = now;

    // WASD
    const step = MOVE_SPEED * dt;
    let f = 0;
    let s = 0;
    if (keys.has('w') || keys.has('arrowup')) f += step;
    if (keys.has('s') || keys.has('arrowdown')) f -= step;
    if (keys.has('d') || keys.has('arrowright')) s += step;
    if (keys.has('a') || keys.has('arrowleft')) s -= step;
    if (f !== 0 || s !== 0) {
      glide = null;
      moveBy(f, s);
    }

    // Click-to-move glide
    if (glide) {
      const t = Math.min(1, (now - glide.t0) / GLIDE_MS);
      const e = easeInOut(t);
      camera.position.x = glide.fromX + (glide.toX - glide.fromX) * e;
      camera.position.z = glide.fromZ + (glide.toZ - glide.fromZ) * e;
      if (t >= 1) glide = null;
    }

    // Floor follow (keep eye height above whatever's underfoot). Ray from just
    // above the eye downward so a ceiling overhead is never mistaken for floor.
    const fy = floorYAt(camera.position.x, camera.position.z, camera.position.y + 0.2);
    if (fy !== null) {
      camera.position.y += (fy + EYE - camera.position.y) * Math.min(1, dt * 12);
    }
    applyLook();
    renderer.render(scene, camera);
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
  args.onReady?.();

  return {
    dispose(): void {
      stopped = true;
      resizeObs.disconnect();
      renderer.domElement.removeEventListener('pointerdown', onDown);
      renderer.domElement.removeEventListener('pointermove', onMove);
      renderer.domElement.removeEventListener('pointerup', onUp);
      renderer.domElement.removeEventListener('pointercancel', onUp);
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      pmrem.dispose();
      renderer.dispose();
      if (renderer.domElement.parentElement === args.mountEl) {
        args.mountEl.removeChild(renderer.domElement);
      }
    },
  };
};

const prettify = (raw: string): string =>
  raw
    .replace(/[._]\d+$/, '')
    .replace(/[._]/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
