/**
 * Sequential tour stepper — turns the villa into ONE connected, ordered walk
 * (the client's "جولة مترابطة"): start outside, step through the grounds, enter,
 * then room-by-room, in a fixed order. Bottom-centre pill with Prev / Next, the
 * current stop name + position ("3 / 6"), and an Auto-pilot toggle that advances
 * on a timer (3DVista's "Auto Pilot"). It drives the SAME navigator the rooms
 * menu + hotspots use, so the walk transition + crossfade apply.
 */

export interface TourStop {
  id: string;
  name: string;
}

export interface TourStepperArgs {
  hostEl: HTMLElement;
  stops: readonly TourStop[];
  currentId: string;
  /** Advance/teleport to a stop (caller wires the walk transition). */
  onGo: (id: string) => void;
  /** Seconds between auto-pilot steps. */
  autoIntervalSec?: number;
}

export interface TourStepperHandle {
  setCurrent(id: string): void;
  dispose(): void;
}

function injectStyles(): void {
  if (typeof document === 'undefined' || document.getElementById('viewer-tour-style')) return;
  const s = document.createElement('style');
  s.id = 'viewer-tour-style';
  s.textContent = `
.viewer-tour{position:absolute;bottom:calc(20px + env(safe-area-inset-bottom));left:50%;
  transform:translateX(-50%);z-index:31;display:flex;align-items:center;gap:6px;
  border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:5px;
  background:rgba(12,16,24,.66);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  box-shadow:0 8px 28px rgba(0,0,0,.45);pointer-events:auto;
  font:600 12.5px/1 system-ui,-apple-system,Segoe UI,'Cairo',sans-serif;color:#f5f7fb}
.viewer-tour-btn{width:34px;height:34px;flex:0 0 auto;border:0;border-radius:50%;cursor:pointer;
  background:rgba(255,255,255,.08);color:#f5f7fb;font-size:15px;display:grid;place-items:center;
  transition:background .14s ease}
.viewer-tour-btn:hover:not(:disabled){background:rgba(255,255,255,.18)}
.viewer-tour-btn:disabled{opacity:.35;cursor:default}
.viewer-tour-btn:focus-visible{outline:2px solid #76c5ff;outline-offset:2px}
.viewer-tour-btn--play.is-playing{background:#76c5ff;color:#0d1018}
.viewer-tour-mid{display:flex;flex-direction:column;align-items:center;gap:2px;
  min-width:118px;padding:0 8px;text-align:center}
.viewer-tour-name{max-width:40vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.viewer-tour-count{font-size:10px;font-weight:700;letter-spacing:.06em;color:rgba(245,247,251,.6)}
.viewer-tour-progress{display:flex;gap:4px;margin-top:1px}
.viewer-tour-dot{width:5px;height:5px;border-radius:50%;background:rgba(245,247,251,.28)}
.viewer-tour-dot.is-done{background:rgba(118,197,255,.7)}
.viewer-tour-dot.is-current{background:#fff;transform:scale(1.25)}
`;
  document.head.append(s);
}

export const mountTourStepper = (args: TourStepperArgs): TourStepperHandle => {
  injectStyles();
  const stops = args.stops;
  const intervalMs = (args.autoIntervalSec ?? 7) * 1000;
  let idx = Math.max(
    0,
    stops.findIndex((s) => s.id === args.currentId),
  );
  let playing = false;
  let timer: ReturnType<typeof setTimeout> | null = null;

  const bar = document.createElement('div');
  bar.className = 'viewer-tour';
  bar.setAttribute('role', 'group');
  bar.setAttribute('aria-label', 'Guided tour');

  const prev = document.createElement('button');
  prev.type = 'button';
  prev.className = 'viewer-tour-btn';
  prev.title = 'Previous stop';
  prev.setAttribute('aria-label', 'Previous stop');
  prev.textContent = '◂';

  const play = document.createElement('button');
  play.type = 'button';
  play.className = 'viewer-tour-btn viewer-tour-btn--play';
  play.title = 'Auto-pilot the tour';
  play.setAttribute('aria-label', 'Play guided tour');
  play.textContent = '▶';

  const next = document.createElement('button');
  next.type = 'button';
  next.className = 'viewer-tour-btn';
  next.title = 'Next stop';
  next.setAttribute('aria-label', 'Next stop');
  next.textContent = '▸';

  const mid = document.createElement('div');
  mid.className = 'viewer-tour-mid';
  const nameEl = document.createElement('span');
  nameEl.className = 'viewer-tour-name';
  const progress = document.createElement('div');
  progress.className = 'viewer-tour-progress';
  const dots = stops.map(() => {
    const d = document.createElement('span');
    d.className = 'viewer-tour-dot';
    progress.appendChild(d);
    return d;
  });
  const count = document.createElement('span');
  count.className = 'viewer-tour-count';
  mid.append(nameEl, progress);

  bar.append(prev, mid, play, next);
  args.hostEl.appendChild(bar);

  const paint = (): void => {
    const stop = stops[idx];
    nameEl.textContent = stop?.name ?? '';
    prev.disabled = idx <= 0;
    next.disabled = idx >= stops.length - 1;
    dots.forEach((d, i) => {
      d.classList.toggle('is-done', i < idx);
      d.classList.toggle('is-current', i === idx);
    });
    play.classList.toggle('is-playing', playing);
    play.textContent = playing ? '❚❚' : '▶';
    play.setAttribute('aria-label', playing ? 'Pause guided tour' : 'Play guided tour');
    void count;
  };

  const go = (target: number): void => {
    if (target < 0 || target >= stops.length) return;
    idx = target;
    const stop = stops[idx];
    if (stop) args.onGo(stop.id);
    paint();
  };

  const scheduleAuto = (): void => {
    if (!playing) return;
    timer = setTimeout(() => {
      if (!playing) return;
      if (idx >= stops.length - 1) {
        stopAuto(); // reached the end
        return;
      }
      go(idx + 1);
      scheduleAuto();
    }, intervalMs);
  };
  const stopAuto = (): void => {
    playing = false;
    if (timer) clearTimeout(timer);
    timer = null;
    paint();
  };
  const startAuto = (): void => {
    playing = true;
    paint();
    // If we're already at the last stop, restart from the beginning.
    if (idx >= stops.length - 1) go(0);
    scheduleAuto();
  };

  prev.addEventListener('click', () => {
    stopAuto();
    go(idx - 1);
  });
  next.addEventListener('click', () => {
    stopAuto();
    go(idx + 1);
  });
  play.addEventListener('click', () => (playing ? stopAuto() : startAuto()));

  paint();

  return {
    setCurrent(id): void {
      const found = stops.findIndex((s) => s.id === id);
      if (found >= 0) idx = found;
      paint();
    },
    dispose(): void {
      if (timer) clearTimeout(timer);
      bar.remove();
    },
  };
};
