/**
 * Multilingual + RTL helpers (FR-TVS-INT-003 + FR-TVS-INT-004).
 *
 * The viewer's chrome adapts direction based on the active locale. RTL
 * languages mirror the compass + controls panel but never the panorama
 * itself (the panorama is real-world content; mirroring it would invert
 * exit signs etc.).
 */

const RTL_LANGS = new Set(['ar', 'he', 'fa', 'ur']);

export type Direction = 'ltr' | 'rtl';

export const directionForLocale = (locale: string): Direction => {
  const base = locale.split('-')[0]?.toLowerCase() ?? 'en';
  return RTL_LANGS.has(base) ? 'rtl' : 'ltr';
};

/** Pick the best locale match from a list of supported tours' languages. */
export const pickBestLocale = (
  requested: readonly string[],
  supported: readonly string[],
  fallback: string,
): string => {
  for (const req of requested) {
    const reqBase = req.split('-')[0]?.toLowerCase();
    if (reqBase === undefined) continue;
    // Exact match first.
    const exact = supported.find((s) => s.toLowerCase() === req.toLowerCase());
    if (exact !== undefined) return exact;
    // Then base-language match.
    const base = supported.find((s) => s.split('-')[0]?.toLowerCase() === reqBase);
    if (base !== undefined) return base;
  }
  return fallback;
};

/** WCAG 2.1 AA contrast ratio between two hex / rgb colours. */
export const contrastRatio = (
  foreground: { r: number; g: number; b: number },
  background: { r: number; g: number; b: number },
): number => {
  const lum = (c: { r: number; g: number; b: number }): number => {
    const linear = (k: number): number => {
      const v = k / 255;
      return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * linear(c.r) + 0.7152 * linear(c.g) + 0.0722 * linear(c.b);
  };
  const a = lum(foreground);
  const b = lum(background);
  const lighter = Math.max(a, b);
  const darker = Math.min(a, b);
  return (lighter + 0.05) / (darker + 0.05);
};

export const meetsWcagAa = (ratio: number, kind: 'normal' | 'large' = 'normal'): boolean =>
  kind === 'large' ? ratio >= 3 : ratio >= 4.5;
