/**
 * Room selector — a single collapsed trigger (bottom-left) that opens a grouped
 * room menu, the pattern every pro tour uses (Kuula / 3DVista / CloudPano):
 * the scene list lives behind ONE icon instead of an always-on strip eating the
 * top of the canvas. The trigger shows the current room name; tapping it opens a
 * panel listing every room grouped by floor, flagging the current + visited
 * scenes. Picking a room teleports (with the walk transition) and closes.
 */

export interface RoomSelectorEntry {
  id: string;
  name: string;
  /** Optional floor/group heading (e.g. 'Ground floor'). Rows with the same
   *  group render under one heading, in first-seen order. */
  group?: string;
}

export interface RoomSelectorArgs {
  hostEl: HTMLElement;
  rooms: readonly RoomSelectorEntry[];
  currentId: string;
  onSelect: (id: string) => void;
}

export interface RoomSelectorHandle {
  setCurrent(id: string): void;
  dispose(): void;
}

function injectStyles(): void {
  if (typeof document === 'undefined' || document.getElementById('viewer-rooms-style')) return;
  const s = document.createElement('style');
  s.id = 'viewer-rooms-style';
  s.textContent = `
.viewer-rooms-fab{position:absolute;bottom:calc(20px + env(safe-area-inset-bottom));
  inset-inline-start:20px;z-index:32;display:flex;align-items:center;gap:9px;cursor:pointer;
  border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:9px 15px 9px 12px;
  background:rgba(12,16,24,.66);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);
  box-shadow:0 8px 28px rgba(0,0,0,.45);color:#f5f7fb;
  font:600 13px/1 system-ui,-apple-system,Segoe UI,'Cairo',sans-serif;pointer-events:auto;
  transition:background .16s ease,transform .16s ease}
.viewer-rooms-fab:hover{background:rgba(22,28,40,.82);transform:translateY(-1px)}
.viewer-rooms-fab:focus-visible{outline:2px solid #76c5ff;outline-offset:3px}
.viewer-rooms-fab-ico{width:18px;height:18px;flex:0 0 auto;opacity:.95}
.viewer-rooms-fab-name{max-width:42vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.viewer-rooms-fab-caret{opacity:.6;font-size:10px;transform:translateY(1px)}

.viewer-rooms-panel{position:absolute;bottom:calc(72px + env(safe-area-inset-bottom));
  inset-inline-start:20px;z-index:33;width:min(86vw,272px);max-height:62vh;overflow-y:auto;
  border:1px solid rgba(255,255,255,.14);border-radius:16px;padding:8px;
  background:rgba(12,16,24,.82);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);
  box-shadow:0 18px 48px rgba(0,0,0,.55);pointer-events:auto;
  transform-origin:bottom left;animation:viewer-rooms-pop .14s ease-out}
[dir='rtl'] .viewer-rooms-panel{transform-origin:bottom right}
@keyframes viewer-rooms-pop{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:none}}
.viewer-rooms-panel[hidden]{display:none}
.viewer-rooms-group{margin:6px 10px 4px;font:700 10.5px/1 system-ui,-apple-system,Segoe UI,'Cairo',sans-serif;
  letter-spacing:.08em;text-transform:uppercase;color:rgba(245,247,251,.5)}
.viewer-rooms-row{display:flex;align-items:center;gap:10px;width:100%;cursor:pointer;border:0;
  background:transparent;border-radius:10px;padding:10px 12px;text-align:start;
  font:600 13.5px/1.1 system-ui,-apple-system,Segoe UI,'Cairo',sans-serif;color:#cfd8e6;
  transition:background .14s ease,color .14s ease}
.viewer-rooms-row:hover{background:rgba(255,255,255,.08);color:#fff}
.viewer-rooms-row:focus-visible{outline:2px solid #76c5ff;outline-offset:-2px}
.viewer-rooms-row.is-current{background:#fff;color:#0d1018;font-weight:700}
.viewer-rooms-dot{width:7px;height:7px;flex:0 0 auto;border-radius:50%;
  border:1.5px solid rgba(245,247,251,.4);background:transparent}
.viewer-rooms-row.is-visited .viewer-rooms-dot{background:#5af0a4;border-color:#5af0a4}
.viewer-rooms-row.is-current .viewer-rooms-dot{background:#0d1018;border-color:#0d1018}
.viewer-rooms-name{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
`;
  document.head.append(s);
}

const FLOORPLAN_ICON =
  "<svg class='viewer-rooms-fab-ico' viewBox='0 0 24 24' fill='none' stroke='currentColor' " +
  "stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'>" +
  "<path d='M3 3h18v18H3z'/><path d='M3 10h9M12 3v18M12 14h9'/></svg>";

export const mountRoomSelector = (args: RoomSelectorArgs): RoomSelectorHandle => {
  injectStyles();
  let current = args.currentId;
  let open = false;
  const visited = new Set<string>([current]);
  const rowById = new Map<string, HTMLButtonElement>();

  // ── Trigger (always visible, shows current room) ──────────────────────
  const fab = document.createElement('button');
  fab.type = 'button';
  fab.className = 'viewer-rooms-fab';
  fab.setAttribute('aria-haspopup', 'true');
  fab.setAttribute('aria-expanded', 'false');
  fab.setAttribute('aria-label', 'Rooms menu');
  const fabName = document.createElement('span');
  fabName.className = 'viewer-rooms-fab-name';
  const caret = document.createElement('span');
  caret.className = 'viewer-rooms-fab-caret';
  caret.textContent = '▲';
  fab.innerHTML = FLOORPLAN_ICON;
  fab.append(fabName, caret);

  // ── Panel (grouped room list) ─────────────────────────────────────────
  const panel = document.createElement('div');
  panel.className = 'viewer-rooms-panel';
  panel.setAttribute('role', 'menu');
  panel.setAttribute('aria-label', 'Rooms');
  panel.hidden = true;

  let lastGroup: string | undefined;
  for (const room of args.rooms) {
    if (room.group && room.group !== lastGroup) {
      const h = document.createElement('div');
      h.className = 'viewer-rooms-group';
      h.textContent = room.group;
      panel.appendChild(h);
      lastGroup = room.group;
    }
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'viewer-rooms-row';
    row.setAttribute('role', 'menuitem');
    const dot = document.createElement('span');
    dot.className = 'viewer-rooms-dot';
    const name = document.createElement('span');
    name.className = 'viewer-rooms-name';
    name.textContent = room.name;
    row.append(dot, name);
    row.addEventListener('click', () => {
      close();
      if (room.id !== current) args.onSelect(room.id);
    });
    panel.appendChild(row);
    rowById.set(room.id, row);
  }

  const paint = (): void => {
    const cur = args.rooms.find((r) => r.id === current);
    fabName.textContent = cur?.name ?? 'Rooms';
    for (const [id, row] of rowById) {
      row.classList.toggle('is-current', id === current);
      row.classList.toggle('is-visited', visited.has(id) && id !== current);
      row.setAttribute('aria-current', id === current ? 'true' : 'false');
    }
  };

  function open_(): void {
    if (open) return;
    open = true;
    panel.hidden = false;
    fab.setAttribute('aria-expanded', 'true');
    caret.textContent = '▼';
    rowById.get(current)?.scrollIntoView({ block: 'nearest' });
    setTimeout(() => document.addEventListener('pointerdown', onOutside, true), 0);
    document.addEventListener('keydown', onKey, true);
  }
  function close(): void {
    if (!open) return;
    open = false;
    panel.hidden = true;
    fab.setAttribute('aria-expanded', 'false');
    caret.textContent = '▲';
    document.removeEventListener('pointerdown', onOutside, true);
    document.removeEventListener('keydown', onKey, true);
  }
  const onOutside = (e: Event): void => {
    const t = e.target as Node;
    if (!panel.contains(t) && !fab.contains(t)) close();
  };
  const onKey = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      close();
      fab.focus();
    }
  };
  fab.addEventListener('click', () => (open ? close() : open_()));

  paint();
  args.hostEl.append(fab, panel);

  return {
    setCurrent(id): void {
      current = id;
      visited.add(id);
      paint();
    },
    dispose(): void {
      close();
      fab.remove();
      panel.remove();
    },
  };
};
