/**
 * First-paint instrumentation (FR-TVS-RND-002 — first panorama interactive
 * in ≤ 2.5s on 10 Mbps).
 *
 * The viewer marks four named timestamps via `performance.mark()` so the
 * analytics pipeline (S24) + a real-user budget alarm can compare to the
 * NFR. Names land on `paint:nova:*` so they don't collide with built-in
 * Paint Timing entries.
 *
 *   paint:nova:boot       — main.ts starts
 *   paint:nova:capability — backend detected
 *   paint:nova:tile-0     — first LOD tile decoded
 *   paint:nova:interactive — render loop has produced its first frame +
 *                            the user input layer is bound
 *
 * `reportFirstPaint()` returns a `FirstPaintMeasurement` once all four are
 * present; analytics emits this as a `viewer.first_paint` event.
 */

export interface FirstPaintMeasurement {
  bootToCapabilityMs: number;
  capabilityToFirstTileMs: number;
  firstTileToInteractiveMs: number;
  bootToInteractiveMs: number;
  /** True when `bootToInteractiveMs <= 2500`. */
  metBudget: boolean;
}

const MARK_PREFIX = 'paint:nova';
const BOOT = `${MARK_PREFIX}:boot`;
const CAPABILITY = `${MARK_PREFIX}:capability`;
const TILE_0 = `${MARK_PREFIX}:tile-0`;
const INTERACTIVE = `${MARK_PREFIX}:interactive`;
const BUDGET_MS = 2_500;

export interface PerformanceLike {
  mark?(name: string): void;
  getEntriesByName?(name: string): readonly { startTime: number }[];
  now(): number;
}

const performanceOrShim = (): PerformanceLike =>
  (globalThis as { performance?: PerformanceLike }).performance ?? {
    now: () => Date.now(),
  };

export const markFirstPaintBoot = (perf: PerformanceLike = performanceOrShim()): void => {
  perf.mark?.(BOOT);
};

export const markFirstPaintCapability = (perf: PerformanceLike = performanceOrShim()): void => {
  perf.mark?.(CAPABILITY);
};

export const markFirstPaintFirstTile = (perf: PerformanceLike = performanceOrShim()): void => {
  perf.mark?.(TILE_0);
};

export const markFirstPaintInteractive = (perf: PerformanceLike = performanceOrShim()): void => {
  perf.mark?.(INTERACTIVE);
};

const readMark = (perf: PerformanceLike, name: string): number | null => {
  const entries = perf.getEntriesByName?.(name);
  if (entries === undefined || entries.length === 0) return null;
  return entries[entries.length - 1]?.startTime ?? null;
};

export const reportFirstPaint = (
  perf: PerformanceLike = performanceOrShim(),
): FirstPaintMeasurement | null => {
  const boot = readMark(perf, BOOT);
  const capability = readMark(perf, CAPABILITY);
  const firstTile = readMark(perf, TILE_0);
  const interactive = readMark(perf, INTERACTIVE);
  if (boot === null || capability === null || firstTile === null || interactive === null) {
    return null;
  }
  return {
    bootToCapabilityMs: capability - boot,
    capabilityToFirstTileMs: firstTile - capability,
    firstTileToInteractiveMs: interactive - firstTile,
    bootToInteractiveMs: interactive - boot,
    metBudget: interactive - boot <= BUDGET_MS,
  };
};

/**
 * Test-only synthetic builder so unit tests can assert on the structure
 * without driving real `performance.mark` calls. Pass raw milliseconds
 * for each marker (relative to boot).
 */
export const buildSyntheticFirstPaint = (timings: {
  capabilityMs: number;
  firstTileMs: number;
  interactiveMs: number;
}): FirstPaintMeasurement => ({
  bootToCapabilityMs: timings.capabilityMs,
  capabilityToFirstTileMs: timings.firstTileMs - timings.capabilityMs,
  firstTileToInteractiveMs: timings.interactiveMs - timings.firstTileMs,
  bootToInteractiveMs: timings.interactiveMs,
  metBudget: timings.interactiveMs <= BUDGET_MS,
});
