import { FallbackSanitiser } from '@nova/viewer-core';

import { POI_TYPE_LABELS, type PoiTypeCode, type ViewerPoi } from './poi-types';

/**
 * Per-POI-type card-body renderer. Each fn returns an `HTMLElement` that
 * the overlay manager puts inside a shared `.poi-card` shell (title + close
 * button + content slot + footer).
 *
 * The contract is intentionally tiny:
 *   - never bind global listeners (only listeners on the returned element)
 *   - never reach outside the returned subtree
 *   - return a *new* element each call (no caching) — the overlay manager
 *     owns lifecycle + DOM removal
 *
 * Sanitisation: POI-08 HTML routes through `FallbackSanitiser`; production
 * may swap in DOMPurify behind the same `Sanitiser` interface (S39 hardening).
 */

const sanitiser = new FallbackSanitiser();

// model-viewer is loaded lazily from Google's CDN (same build AR-Studio ships)
// so the viewer bundle stays small — only product cards that actually have a
// 3D model pay the cost, and only on first open.
const MODEL_VIEWER_CDN =
  'https://ajax.googleapis.com/ajax/libs/model-viewer/4.0.0/model-viewer.min.js';
let modelViewerLoading: Promise<void> | null = null;
const ensureModelViewer = (): Promise<void> => {
  if (typeof customElements !== 'undefined' && customElements.get('model-viewer')) {
    return Promise.resolve();
  }
  if (modelViewerLoading) return modelViewerLoading;
  modelViewerLoading = new Promise<void>((resolve) => {
    const s = document.createElement('script');
    s.type = 'module';
    s.src = MODEL_VIEWER_CDN;
    s.onload = () => resolve();
    s.onerror = () => resolve(); // fall back to poster/specs if the CDN is blocked
    document.head.append(s);
  });
  return modelViewerLoading;
};

// Minimal structural types over model-viewer's materials API (we don't pull in
// @google/model-viewer's types — only the bits we touch). model-viewer exposes
// `.model.materials[i].pbrMetallicRoughness` with a base-colour getter + setter
// once the GLB has loaded.
interface MvPbr {
  baseColorFactor: readonly number[];
  setBaseColorFactor(value: string | number[]): void;
}
interface MvMaterial {
  name?: string;
  pbrMetallicRoughness: MvPbr;
}
interface ModelViewerEl extends HTMLElement {
  model?: { materials: MvMaterial[] };
}

export interface ProductSwatch {
  label: string;
  hex: string;
}

/** Build the 3D/AR hero: an interactive <model-viewer> (orbit + auto-spin), a
 *  "View in your room" AR button, and — when the product declares swatches — a
 *  live colour configurator that recolours the model's materials at runtime via
 *  model-viewer's materials API (no GLB re-authoring; this is the `overrideColor`
 *  fallback path, since our GLBs carry no KHR_materials_variants). */
const buildProductModel = (
  modelUrl: string,
  poster: string,
  title: string,
  swatches: readonly ProductSwatch[] = [],
  materialNames?: readonly string[],
): HTMLElement => {
  void ensureModelViewer();
  const wrap = div('poi-card-product-model-wrap');
  const mv = document.createElement('model-viewer') as ModelViewerEl;
  mv.className = 'poi-card-product-model';
  mv.setAttribute('src', modelUrl);
  if (poster.length > 0) mv.setAttribute('poster', poster);
  mv.setAttribute('alt', `${title} — 3D model`);
  mv.setAttribute('camera-controls', '');
  mv.setAttribute('touch-action', 'pan-y');
  mv.setAttribute('auto-rotate', '');
  mv.setAttribute('auto-rotate-delay', '2500');
  mv.setAttribute('rotation-per-second', '22deg');
  mv.setAttribute('interaction-prompt', 'auto');
  mv.setAttribute('camera-orbit', '-20deg 78deg 105%');
  mv.setAttribute('shadow-intensity', '1');
  mv.setAttribute('shadow-softness', '0.75');
  mv.setAttribute('environment-image', 'neutral');
  mv.setAttribute('exposure', '1.05');
  mv.setAttribute('loading', 'eager');
  mv.setAttribute('reveal', 'auto');
  // AR: real-world scale, floor placement. model-viewer picks the first AR mode
  // the device supports (WebXR on Android, Quick Look on iOS, Scene Viewer).
  mv.setAttribute('ar', '');
  mv.setAttribute('ar-modes', 'webxr scene-viewer quick-look');
  mv.setAttribute('ar-scale', 'fixed');
  mv.setAttribute('ar-placement', 'floor');
  const arBtn = document.createElement('button');
  arBtn.type = 'button';
  arBtn.slot = 'ar-button';
  arBtn.className = 'poi-card-ar-btn';
  arBtn.textContent = 'View in your room';
  mv.appendChild(arBtn);
  wrap.appendChild(mv);

  if (swatches.length > 0) {
    wrap.appendChild(buildColourConfigurator(mv, swatches, materialNames));
  }
  return wrap;
};

/** Colour configurator: a swatch rail under the 3D hero. Captures each target
 *  material's original base colour on load (for "Original"), then recolours live
 *  on tap. Targets materials by NAME (e.g. only the chair's "Brown leather", not
 *  its metal legs); falls back to all materials when no names are declared. */
const buildColourConfigurator = (
  mv: ModelViewerEl,
  swatches: readonly ProductSwatch[],
  materialNames?: readonly string[],
): HTMLElement => {
  const rail = div('poi-card-swatches');
  const label = document.createElement('span');
  label.className = 'poi-card-swatches-label';
  label.textContent = 'Finish';
  rail.appendChild(label);

  let originals: number[][] = [];
  const wanted = materialNames?.map((n) => n.toLowerCase());
  const targets = (): number[] => {
    const mats = mv.model?.materials ?? [];
    if (!wanted || wanted.length === 0) return mats.map((_, i) => i);
    const matched = mats
      .map((m, i) => ({ i, name: (m.name ?? '').toLowerCase() }))
      .filter((m) => wanted.includes(m.name))
      .map((m) => m.i);
    // If the named materials aren't found (e.g. a re-export renamed them),
    // fail safe to recolouring everything rather than silently doing nothing.
    return matched.length > 0 ? matched : mats.map((_, i) => i);
  };
  const applyHex = (hex: string): void => {
    const mats = mv.model?.materials ?? [];
    for (const i of targets()) mats[i]?.pbrMetallicRoughness.setBaseColorFactor(hex);
  };
  const applyOriginal = (): void => {
    const mats = mv.model?.materials ?? [];
    targets().forEach((i, k) => {
      const o = originals[k];
      if (o) mats[i]?.pbrMetallicRoughness.setBaseColorFactor([...o]);
    });
  };

  const dots: HTMLButtonElement[] = [];
  const select = (el: HTMLButtonElement): void => {
    for (const d of dots) d.classList.toggle('is-active', d === el);
  };

  const mkDot = (cls: string, title: string, onPick: () => void): HTMLButtonElement => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = `poi-card-swatch ${cls}`;
    b.title = title;
    b.setAttribute('aria-label', title);
    b.disabled = true; // enabled once the model + materials are ready
    b.addEventListener('click', () => {
      onPick();
      select(b);
    });
    dots.push(b);
    return b;
  };

  const original = mkDot('poi-card-swatch--original is-active', 'Original', applyOriginal);
  rail.appendChild(original);
  for (const sw of swatches) {
    const dot = mkDot('', sw.label, () => applyHex(sw.hex));
    dot.style.setProperty('--swatch', sw.hex);
    rail.appendChild(dot);
  }

  mv.addEventListener('load', () => {
    const mats = mv.model?.materials ?? [];
    originals = targets().map((i) => [...(mats[i]?.pbrMetallicRoughness.baseColorFactor ?? [])]);
    for (const d of dots) d.disabled = false;
  });

  return rail;
};

export interface PoiRenderContext {
  /** Active locale (e.g. 'en-US' / 'ar-KW'). Carded copy may localise. */
  locale: string;
  /** When true, the card should mirror inline icons for RTL. */
  isRtl: boolean;
  /** Callback when the visitor takes a CTA action (lead capture, click-through). */
  onCta?: (kind: string, payload: Record<string, unknown>) => void;
}

type CardRenderer = (poi: ViewerPoi, ctx: PoiRenderContext) => HTMLElement;

const div = (cls: string): HTMLDivElement => {
  const el = document.createElement('div');
  el.className = cls;
  return el;
};

const heading = (text: string): HTMLHeadingElement => {
  const h = document.createElement('h3');
  h.className = 'poi-card-title';
  h.textContent = text;
  return h;
};

const paragraph = (text: string): HTMLParagraphElement => {
  const p = document.createElement('p');
  p.textContent = text;
  return p;
};

const safeString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');

const safeNumber = (raw: unknown): number | null =>
  typeof raw === 'number' && Number.isFinite(raw) ? raw : null;

const renderImage: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--gallery');
  const images = (poi.payload.images as { url: string; alt?: string }[] | undefined) ?? [];
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const grid = div('poi-card-gallery');
  for (const img of images.slice(0, 12)) {
    const fig = document.createElement('figure');
    const el = document.createElement('img');
    el.src = img.url;
    el.alt = img.alt ?? '';
    el.loading = 'lazy';
    el.referrerPolicy = 'no-referrer';
    fig.appendChild(el);
    grid.appendChild(fig);
  }
  root.appendChild(grid);
  if (safeString(poi.payload.description).length > 0) {
    root.appendChild(paragraph(safeString(poi.payload.description)));
  }
  return root;
};

const renderVideo: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--video');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const v = document.createElement('video');
  v.src = safeString(poi.payload.videoUrl);
  v.controls = true;
  v.playsInline = true;
  v.preload = 'metadata';
  v.crossOrigin = 'anonymous';
  v.muted = poi.payload.muted !== false;
  if (poi.payload.loop === true) v.loop = true;
  const poster = safeString(poi.payload.posterUrl);
  if (poster.length > 0) v.poster = poster;
  root.appendChild(v);
  return root;
};

