const formatCurrency = (priceMinor: number, currency: string, locale: string): string => {
  try {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
    }).format(priceMinor / 100);
  } catch {
    return `${(priceMinor / 100).toFixed(2)} ${currency}`;
  }
};

const renderProductCard: CardRenderer = (poi, ctx) => {
  const root = div('poi-card-body poi-card-body--product');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  // Hero media, in order of richness: a real 3D model (orbit + AR) → a
  // product video → a product image. The 3D model IS the product, so it's
  // always the most relevant hero when present.
  const modelUrl = safeString(poi.payload.modelUrl);
  const videoUrl = safeString(poi.payload.videoUrl);
  const imageUrl = safeString(poi.payload.imageUrl);
  if (modelUrl.length > 0) {
    const rawSwatches = Array.isArray(poi.payload.swatches) ? poi.payload.swatches : [];
    const swatches: ProductSwatch[] = rawSwatches
      .map((s) => {
        const o = (s ?? {}) as Record<string, unknown>;
        return { label: safeString(o.label), hex: safeString(o.hex) };
      })
      .filter((s) => s.hex.length > 0);
    const matNames = Array.isArray(poi.payload.swatchMaterials)
      ? poi.payload.swatchMaterials.filter((n): n is string => typeof n === 'string')
      : undefined;
    root.appendChild(
      buildProductModel(modelUrl, imageUrl, safeString(poi.payload.title), swatches, matNames),
    );
  } else if (videoUrl.length > 0) {
    const v = document.createElement('video');
    v.src = videoUrl;
    v.controls = true;
    v.playsInline = true;
    v.muted = true;
    v.preload = 'metadata';
    if (imageUrl.length > 0) v.poster = imageUrl;
    v.className = 'poi-card-product-video';
    root.appendChild(v);
  } else if (imageUrl.length > 0) {
    const img = document.createElement('img');
    img.src = imageUrl;
    img.alt = safeString(poi.payload.title) || 'Product';
    img.loading = 'lazy';
    img.className = 'poi-card-product-img';
    root.appendChild(img);
  }
  const meta = div('poi-card-product-meta');
  const priceMinor = safeNumber(poi.payload.priceMinor) ?? 0;
  const currency = safeString(poi.payload.currency) || 'USD';
  const price = document.createElement('strong');
  price.className = 'poi-card-product-price';
  price.textContent = formatCurrency(priceMinor, currency, ctx.locale);
  meta.appendChild(price);

  const inv = safeString(poi.payload.inventoryHint);
  if (inv.length > 0) {
    const badge = document.createElement('span');
    badge.className = `poi-card-badge poi-card-badge--${inv.toLowerCase().replace('_', '-')}`;
    badge.textContent = inv.replace('_', ' ').toLowerCase();
    meta.appendChild(badge);
  }
  root.appendChild(meta);

  const description = safeString(poi.payload.description);
  if (description.length > 0) {
    root.appendChild(paragraph(description));
  }

  // Specs list — payload.specs is an array of { label, value } (or strings).
  const specs = poi.payload.specs;
  if (Array.isArray(specs) && specs.length > 0) {
    const ul = document.createElement('ul');
    ul.className = 'poi-card-product-specs';
    for (const s of specs) {
      const li = document.createElement('li');
      if (s && typeof s === 'object' && 'label' in (s as Record<string, unknown>)) {
        const labelEl = document.createElement('span');
        labelEl.className = 'spec-label';
        labelEl.textContent = safeString((s as Record<string, unknown>).label);
        const valueEl = document.createElement('span');
        valueEl.className = 'spec-value';
        valueEl.textContent = safeString((s as Record<string, unknown>).value);
        li.append(labelEl, valueEl);
      } else {
        li.textContent = safeString(s);
      }
      ul.appendChild(li);
    }
    root.appendChild(ul);
  }

  const sku = safeString(poi.payload.productSku);
  if (sku.length > 0) {
    const small = document.createElement('small');
    small.className = 'poi-card-product-sku';
    small.textContent = `SKU ${sku}`;
    root.appendChild(small);
  }

  const cta = document.createElement('button');
  cta.type = 'button';
  cta.className = 'poi-card-cta';
  cta.textContent = 'Add to cart';
  cta.addEventListener('click', () => ctx.onCta?.('add_to_cart', { sku, priceMinor, currency }));
  root.appendChild(cta);
  return root;
};

const renderVideoHotspot: CardRenderer = (poi) => {
  const root = div('poi-card-body poi-card-body--video');
  if (safeString(poi.payload.title).length > 0) {
    root.appendChild(heading(safeString(poi.payload.title)));
  }
  const v = document.createElement('video');
  v.src = safeString(poi.payload.videoUrl);
  v.controls = true;
  v.playsInline = true;
  v.preload = 'metadata';
  root.appendChild(v);
  const triggers =
    (poi.payload.triggers as
      | { atSeconds: number; actionLabel: string; actionUrl?: string }[]
      | undefined) ?? [];
  if (triggers.length > 0) {
    const list = document.createElement('ol');
    list.className = 'poi-card-video-triggers';
    for (const t of triggers) {
      const li = document.createElement('li');
      li.textContent = `${formatTimestamp(t.atSeconds)} · ${t.actionLabel}`;
      if (safeString(t.actionUrl).length > 0) {
        const a = document.createElement('a');
        a.href = safeString(t.actionUrl);
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.textContent = ' →';
        li.appendChild(a);
      }
      list.appendChild(li);
    }
    root.appendChild(list);
  }
  return root;
};

const formatTimestamp = (seconds: number): string => {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60)
    .toString()
    .padStart(2, '0');
  return `${m}:${s}`;
};

export const POI_CARD_RENDERERS: Record<PoiTypeCode, CardRenderer> = {
  'POI-01': renderImage,
  'POI-02': renderVideo,
  'POI-03': render360Video,
  'POI-04': renderAudio,
  'POI-05': renderIframe,
  'POI-06': renderExternalLink,
  'POI-07': renderText,
  'POI-08': renderHtml,
  'POI-09': renderDownload,
  'POI-10': renderPdf,
  'POI-11': renderForm,
  'POI-12': renderObject3d,
  'POI-13': renderPointCloud,
  'POI-14': renderProductCard,
  'POI-15': renderVideoHotspot,
  'POI-16': renderImage,
};

export const renderUnknownPoiCard = (poi: ViewerPoi): HTMLElement => {
  const root = div('poi-card-body poi-card-body--unknown');
  root.appendChild(heading('Unsupported POI'));
  root.appendChild(
    paragraph(
      `This panorama uses POI type ${poi.typeCode} (${POI_TYPE_LABELS[poi.typeCode] ?? 'unknown'}) which this viewer build does not render. Update the viewer to see it.`,
    ),
  );
  return root;
};
