/**
 * HTML sanitiser contract for POI-08 (HTML POI) — SRS demands payload be
 * sanitised at render time, not at storage time, so that a tightened
 * whitelist applies retroactively to already-stored payloads. The
 * production sanitiser will plug DOMPurify into this interface; the lib
 * ships a deterministic, dependency-free fallback that strips dangerous
 * subset (script / on* / data:/javascript: URLs) for tests + SSR previews.
 *
 * The sanitiser is intentionally conservative: a payload that uses any
 * unsafe construct is dropped from the output, not partially-cleaned.
 * Tenants who need richer HTML can ship a custom DOMPurify hook from the
 * dashboard editor; the viewer applies the platform's whitelist as a
 * second-stage gate so a permissive tenant policy can't bypass the
 * platform's invariants.
 */

export interface SanitiserOptions {
  /** Tags allowed in addition to the platform default whitelist. */
  extraAllowedTags?: readonly string[];
  /** Attributes allowed in addition to the platform default. */
  extraAllowedAttrs?: readonly string[];
}

export interface Sanitiser {
  sanitize(html: string, opts?: SanitiserOptions): string;
}

/**
 * Default tag whitelist — covers semantic prose without giving any
 * scripting surface. Headings + lists + tables + media-free formatting.
 * `img`/`video`/`iframe` deliberately NOT allowed inside POI-08 — those
 * payloads have dedicated POI types (POI-01 / POI-02 / POI-05).
 */
export const DEFAULT_ALLOWED_TAGS: readonly string[] = [
  'a',
  'abbr',
  'address',
  'b',
  'blockquote',
  'br',
  'cite',
  'code',
  'dd',
  'del',
  'dfn',
  'div',
  'dl',
  'dt',
  'em',
  'figcaption',
  'figure',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'hr',
  'i',
  'ins',
  'kbd',
  'li',
  'mark',
  'ol',
  'p',
  'pre',
  'q',
  's',
  'samp',
  'section',
  'small',
  'span',
  'strong',
  'sub',
  'sup',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'tr',
  'u',
  'ul',
  'var',
];

export const DEFAULT_ALLOWED_ATTRS: readonly string[] = [
  'href',
  'title',
  'lang',
  'dir',
  'class',
  'role',
  'aria-label',
  'aria-describedby',
  'aria-hidden',
  'rel',
];

/**
 * Dependency-free fallback. Tokenises the input + rebuilds it keeping only
 * whitelisted tags + attributes; strips `<script>`, all `on*` event
 * handlers, and any URL attribute that opens a `javascript:` / `data:` /
 * `vbscript:` scheme. Not as robust as DOMPurify (no shadow DOM, no SVG
 * payload analysis) — production wires DOMPurify behind the same
 * `Sanitiser` interface in S14.5+.
 */
export class FallbackSanitiser implements Sanitiser {
  sanitize(html: string, opts?: SanitiserOptions): string {
    const allowedTags = new Set([...DEFAULT_ALLOWED_TAGS, ...(opts?.extraAllowedTags ?? [])]);
    const allowedAttrs = new Set([...DEFAULT_ALLOWED_ATTRS, ...(opts?.extraAllowedAttrs ?? [])]);

    let cursor = 0;
    let out = '';
    const len = html.length;

    while (cursor < len) {
      const lt = html.indexOf('<', cursor);
      if (lt === -1) {
        out += escapeText(html.slice(cursor));
        break;
      }
      if (lt > cursor) out += escapeText(html.slice(cursor, lt));

      // Bail on `<!--…-->`, `<![CDATA…]>` and CDATA-style raw blocks.
      if (html.startsWith('<!--', lt)) {
        const end = html.indexOf('-->', lt + 4);
        cursor = end === -1 ? len : end + 3;
        continue;
      }
      if (html.startsWith('<![', lt)) {
        const end = html.indexOf(']>', lt + 3);
        cursor = end === -1 ? len : end + 2;
        continue;
      }

      const gt = html.indexOf('>', lt);
      if (gt === -1) {
        out += escapeText(html.slice(lt));
        break;
      }

      const rawTag = html.slice(lt + 1, gt).trim();
      const isClosing = rawTag.startsWith('/');
      const body = isClosing ? rawTag.slice(1) : rawTag;
      const match = /^([a-zA-Z][a-zA-Z0-9-]*)([\s\S]*?)\/?$/.exec(body);
      cursor = gt + 1;
      if (match === null) continue;

      const tagName = match[1]!.toLowerCase();
      const attrSegment = match[2] ?? '';

      // `<script>…</script>` consumes until close.
      if (tagName === 'script' || tagName === 'style') {
        const close = html.indexOf(`</${tagName}`, cursor);
        if (close !== -1) {
          const closeEnd = html.indexOf('>', close);
          cursor = closeEnd === -1 ? len : closeEnd + 1;
        }
        continue;
      }

      if (!allowedTags.has(tagName)) continue;

      if (isClosing) {
        out += `</${tagName}>`;
        continue;
      }

      const attrs = parseAttributes(attrSegment).filter(({ name, value }) => {
        const lowerName = name.toLowerCase();
        if (lowerName.startsWith('on')) return false;
        if (!allowedAttrs.has(lowerName)) return false;
        if (
          lowerName === 'href' ||
          lowerName === 'src' ||
          lowerName === 'cite' ||
          lowerName === 'action'
        ) {
          return isSafeUrl(value);
        }
        return true;
      });
      const attrStr =
        attrs.length === 0
          ? ''
          : ' ' + attrs.map((a) => `${a.name}="${escapeAttr(a.value)}"`).join(' ');
      const selfClosing = VOID_TAGS.has(tagName);
      out += selfClosing ? `<${tagName}${attrStr} />` : `<${tagName}${attrStr}>`;
    }
    return out;
  }
}

const VOID_TAGS = new Set(['br', 'hr']);

interface ParsedAttr {
  name: string;
  value: string;
}

const parseAttributes = (input: string): ParsedAttr[] => {
  const out: ParsedAttr[] = [];
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(input)) !== null) {
    const name = m[1]!;
    const value = m[2] ?? m[3] ?? m[4] ?? '';
    out.push({ name, value });
  }
  return out;
};

const isSafeUrl = (url: string): boolean => {
  const trimmed = url.trim().toLowerCase();
  if (trimmed.length === 0) return true;
  if (trimmed.startsWith('javascript:')) return false;
  if (trimmed.startsWith('vbscript:')) return false;
  if (trimmed.startsWith('data:') && !trimmed.startsWith('data:image/')) return false;
  return true;
};

const escapeText = (s: string): string =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const escapeAttr = (s: string): string =>
  s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
