/**
 * Visual + audio effects layer for the real-photo panorama tour.
 *
 * Twin chips in `procedural-chip-overlay.ts` flip state but a panorama
 * has no real meshes to light up — so we layer CSS overlays + a canvas
 * + Web Audio synth on top of the panorama canvas and drive them from
 * the registry. Each effect is a full-screen overlay because mapping
 * an `anchorM` 3D point to panorama-camera screen coords would need
 * the renderer's projection matrix; keeping effects scene-wide gives
 * an obvious visible response without that plumbing.
 *
 * Layers (z-stacked over the panorama canvas):
 *   - lamp glow      → warm-yellow radial gradient (screen blend)
 *   - tv glow        → animated coloured rectangle (right edge)
 *   - curtain dim    → black overlay, opacity by closed-fraction
 *   - day/night tint → deep blue multiply blend
 *   - rain canvas    → animated raindrops
 *   - doorbell       → Web Audio sine ding-dong (no DOM)
 */
import type { TwinRegistry } from '@nova/digital-twin';

export interface TourEffectsArgs {
  readonly hostEl: HTMLElement;
  readonly registry: TwinRegistry;
  readonly initialSceneId: string;
}

export interface TourEffectsHandle {
  setSceneId(id: string): void;
  refreshFromRegistry(): void;
  setDayNight(on: boolean): void;
  isDayNightOn(): boolean;
  setWeather(on: boolean): void;
  isWeatherOn(): boolean;
  ringDoorbell(): void;
  dispose(): void;
}

export function mountTourEffects(args: TourEffectsArgs): TourEffectsHandle {
  const root = document.createElement('div');
  root.className = 'nova-tour-effects';
  root.style.cssText = `
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 10;
    overflow: hidden;
  `;
  args.hostEl.appendChild(root);

  const lampGlow = document.createElement('div');
  lampGlow.dataset.layer = 'lamp';
  lampGlow.style.cssText = `
    position: absolute;
    inset: 0;
    background: radial-gradient(
      ellipse 75% 55% at 50% 28%,
      rgba(255, 220, 130, 0.55),
      rgba(255, 180, 70, 0.22) 38%,
      rgba(255, 150, 40, 0.06) 65%,
      rgba(0, 0, 0, 0) 80%
    );
    mix-blend-mode: screen;
    opacity: 0;
    transition: opacity 360ms ease;
  `;
  root.appendChild(lampGlow);

  const curtainDim = document.createElement('div');
  curtainDim.dataset.layer = 'curtain';
  curtainDim.style.cssText = `
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.55);
    opacity: 0;
    transition: opacity 420ms ease;
  `;
  root.appendChild(curtainDim);

  const dayNight = document.createElement('div');
  dayNight.dataset.layer = 'daynight';
  dayNight.style.cssText = `
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(8, 14, 48, 0.78), rgba(28, 38, 80, 0.62));
    mix-blend-mode: multiply;
    opacity: 0;
    transition: opacity 600ms ease;
  `;
  root.appendChild(dayNight);

  const tvGlow = document.createElement('div');
  tvGlow.dataset.layer = 'tv';
  tvGlow.style.cssText = `
    position: absolute;
    right: 8%;
    top: 38%;
    width: clamp(160px, 22vw, 340px);
    height: clamp(100px, 14vw, 210px);
    border-radius: 8px;
    background:
      linear-gradient(135deg, rgba(239, 68, 68, 0.85), rgba(59, 130, 246, 0.85), rgba(16, 185, 129, 0.85));
    background-size: 220% 220%;
    box-shadow:
      0 0 60px rgba(99, 102, 241, 0.55),
      0 0 120px rgba(59, 130, 246, 0.35),
      inset 0 0 30px rgba(255, 255, 255, 0.15);
    animation: novaTvFlicker 2.4s linear infinite alternate;
    opacity: 0;
    transition: opacity 260ms ease;
  `;
  root.appendChild(tvGlow);

  const rainCanvas = document.createElement('canvas');
  rainCanvas.dataset.layer = 'rain';
  rainCanvas.style.cssText = `
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    transition: opacity 380ms ease;
  `;
  root.appendChild(rainCanvas);

  const styleSheet = document.createElement('style');
  styleSheet.dataset.owner = 'nova-tour-effects';
  styleSheet.textContent = `
    @keyframes novaTvFlicker {
      0%   { background-position:   0% 50%; filter: brightness(0.95); }
      50%  { background-position: 100% 50%; filter: brightness(1.12); }
      100% { background-position:   0% 50%; filter: brightness(0.92); }
    }
  `;
  document.head.appendChild(styleSheet);

  let currentSceneId = args.initialSceneId;
  let dayNightOn = false;
  let weatherOn = false;
  let rainHandle: number | null = null;
  let drops: { x: number; y: number; len: number; speed: number }[] = [];
  let audioCtx: AudioContext | null = null;

  function getAudioCtx(): AudioContext {
    if (audioCtx === null) {
      const Ctor = window.AudioContext;
      audioCtx = new Ctor();
    }
    return audioCtx;
  }

  function refreshFromRegistry(): void {
    const twins = args.registry.twinsForScene(currentSceneId);
    let lampOn = false;
    let tvOn = false;
    let shadesClosed = 0;
    let shadesTotal = 0;

    for (const twin of twins) {
      const s = twin.state;
      if (s.kind === 'lamp' && s.state.on) lampOn = true;
      if (s.kind === 'media-display' && s.state.playing) tvOn = true;
      if (s.kind === 'shade') {
        shadesTotal += 1;
        if (s.state.position > 0.5) shadesClosed += 1;
      }
    }

    lampGlow.style.opacity = lampOn ? '1' : '0';
    tvGlow.style.opacity = tvOn ? '1' : '0';
    curtainDim.style.opacity = shadesTotal === 0 ? '0' : `${(0.55 * shadesClosed) / shadesTotal}`;
  }

  function setSceneId(id: string): void {
    currentSceneId = id;
    refreshFromRegistry();
  }

  function setDayNight(on: boolean): void {
    dayNightOn = on;
    dayNight.style.opacity = on ? '0.9' : '0';
  }

  function setWeather(on: boolean): void {
    weatherOn = on;
    rainCanvas.style.opacity = on ? '0.85' : '0';
    if (on) startRain();
    else stopRain();
  }

  function startRain(): void {
    if (rainHandle !== null) return;
    const ctx = rainCanvas.getContext('2d');
    if (ctx === null) return;
    rainCanvas.width = rainCanvas.clientWidth;
    rainCanvas.height = rainCanvas.clientHeight;
    drops = [];
    const count = Math.max(160, Math.floor(rainCanvas.width / 8));
    for (let i = 0; i < count; i += 1) {
      drops.push({
        x: Math.random() * rainCanvas.width,
        y: Math.random() * rainCanvas.height,
        len: 8 + Math.random() * 16,
        speed: 5 + Math.random() * 7,
      });
    }
    const tick = (): void => {
      ctx.clearRect(0, 0, rainCanvas.width, rainCanvas.height);
      ctx.strokeStyle = 'rgba(190, 220, 255, 0.55)';
      ctx.lineWidth = 1.3;
      ctx.beginPath();
      for (const d of drops) {
        ctx.moveTo(d.x, d.y);
        ctx.lineTo(d.x - 2, d.y + d.len);
        d.x -= 2;
        d.y += d.speed;
        if (d.y > rainCanvas.height) {
          d.y = -d.len;
          d.x = Math.random() * rainCanvas.width;
        }
      }
      ctx.stroke();
      rainHandle = requestAnimationFrame(tick);
    };
    rainHandle = requestAnimationFrame(tick);
  }

  function stopRain(): void {
    if (rainHandle !== null) {
      cancelAnimationFrame(rainHandle);
      rainHandle = null;
    }
  }

  function ringDoorbell(): void {
    const ctx = getAudioCtx();
    if (ctx.state === 'suspended') void ctx.resume();
    const now = ctx.currentTime;
    const tone = (t: number, freq: number, duration: number): void => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0, now + t);
      gain.gain.linearRampToValueAtTime(0.28, now + t + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, now + t + duration);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now + t);
      osc.stop(now + t + duration);
    };
    tone(0, 830, 0.55);
    tone(0.18, 660, 0.78);
  }

  refreshFromRegistry();

  return {
    setSceneId,
    refreshFromRegistry,
    setDayNight,
    isDayNightOn: () => dayNightOn,
    setWeather,
    isWeatherOn: () => weatherOn,
    ringDoorbell,
    dispose(): void {
      stopRain();
      root.remove();
      styleSheet.remove();
      if (audioCtx !== null) void audioCtx.close();
    },
  };
}
