/**
 * Floor-plan mini-map with a position + facing "radar" — the single highest-trust
 * orientation aid in pro tours (3DVista's interactive floor plan / Matterport's
 * map). A compact top-left panel shows every capture point laid out top-down,
 * the guided route drawn as a connecting line, the CURRENT point highlighted,
 * and a radar cone that rotates with the live camera so you always know where
 * you are AND which way you're looking. Tapping a point teleports there.
 *
 * Layout uses each scene's `minimapAnchor` (normalised 0..1), so it stays a
 * faithful relative map without needing a rendered architectural plan.
 */

export interface FloorplanPoint {
  id: string;
  name: string;
  x: number; // 0..1 (minimapAnchor)
  y: number; // 0..1
}

export interface FloorplanArgs {
  hostEl: HTMLElement;
  points: readonly FloorplanPoint[];
  /** Ordered scene ids — drawn as the route polyline. */
  route: readonly string[];
  currentId: string;
  onJump: (id: string) => void;
  /** Degrees added to the camera yaw to align the cone with the map. */
  northOffsetDeg?: number;
}

export interface FloorplanHandle {
  setCurrent(id: string): void;
  setCamera(yawDeg: number): void;
  dispose(): void;
}

const NS = 'http://www.w3.org/2000/svg';
const VB = 100; // viewBox units
const PAD = 14;

function injectStyles(): void {
  if (typeof document === 'undefined' || document.getElementById('viewer-fplan-style')) return;
  const s = document.createElement('style');
  s.id = 'viewer-fplan-style';
  s.textContent = `
.viewer-fplan{position:absolute;top:calc(16px + env(safe-area-inset-top));inset-inline-start:16px;
  z-index:29;width:172px;border-radius:14px;padding:8px 8px 6px;
  background:rgba(12,16,24,.62);border:1px solid rgba(255,255,255,.14);
  backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);box-shadow:0 8px 28px rgba(0,0,0,.45);
  pointer-events:auto}
.viewer-fplan-title{font:700 9.5px/1 system-ui,-apple-system,Segoe UI,'Cairo',sans-serif;
  letter-spacing:.1em;text-transform:uppercase;color:rgba(245,247,251,.55);margin:1px 2px 6px}
.viewer-fplan svg{display:block;width:100%;height:auto;overflow:visible}
.viewer-fplan-route{fill:none;stroke:rgba(118,197,255,.45);stroke-width:1.4;
  stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3}
.viewer-fplan-dot{cursor:pointer;fill:rgba(245,247,251,.5);stroke:rgba(12,16,24,.7);stroke-width:1;
  transition:fill .15s ease,r .15s ease}
.viewer-fplan-dot:hover{fill:#fff}
.viewer-fplan-dot.is-visited{fill:rgba(90,240,164,.85)}
.viewer-fplan-dot.is-current{fill:#fff}
.viewer-fplan-cone{fill:rgba(118,197,255,.32);stroke:rgba(118,197,255,.85);stroke-width:.6;
  pointer-events:none;transition:opacity .2s ease}
.viewer-fplan-here{fill:#76c5ff;stroke:#0d1018;stroke-width:1.2;pointer-events:none}
.viewer-fplan-label{font:700 8px/1 system-ui,-apple-system,Segoe UI,sans-serif;fill:#fff;
  paint-order:stroke;stroke:rgba(12,16,24,.85);stroke-width:2.4;pointer-events:none}
`;
  document.head.append(s);
}

const sx = (x: number): number => PAD + x * (VB - 2 * PAD);
const sy = (y: number): number => PAD + y * (VB - 2 * PAD);

export const mountFloorplan = (args: FloorplanArgs): FloorplanHandle => {
  injectStyles();
  const byId = new Map(args.points.map((p) => [p.id, p]));
  const visited = new Set<string>([args.currentId]);
  let current = args.currentId;
  const northOffset = args.northOffsetDeg ?? 0;

  const panel = document.createElement('div');
  panel.className = 'viewer-fplan';
  const title = document.createElement('div');
  title.className = 'viewer-fplan-title';
  title.textContent = 'Floor plan';
  panel.appendChild(title);

  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${VB} ${VB}`);
  svg.setAttribute('role', 'img');
  svg.setAttribute('aria-label', 'Tour floor plan');

  // Route polyline (guided order).
  const routePts = args.route
    .map((id) => byId.get(id))
    .filter((p): p is FloorplanPoint => Boolean(p))
    .map((p) => `${sx(p.x).toFixed(1)},${sy(p.y).toFixed(1)}`)
    .join(' ');
  const route = document.createElementNS(NS, 'polyline');
  route.setAttribute('class', 'viewer-fplan-route');
  route.setAttribute('points', routePts);
  svg.appendChild(route);

  // Facing cone (under the dots) — a wedge centred on the current point.
  const cone = document.createElementNS(NS, 'path');
  cone.setAttribute('class', 'viewer-fplan-cone');
  svg.appendChild(cone);

  // Dots + click targets.
  const dotById = new Map<string, SVGCircleElement>();
  for (const p of args.points) {
    const dot = document.createElementNS(NS, 'circle');
    dot.setAttribute('class', 'viewer-fplan-dot');
    dot.setAttribute('cx', sx(p.x).toFixed(1));
    dot.setAttribute('cy', sy(p.y).toFixed(1));
    dot.setAttribute('r', '3.4');
    dot.setAttribute('tabindex', '0');
    dot.setAttribute('role', 'button');
    dot.setAttribute('aria-label', p.name);
    const t = document.createElementNS(NS, 'title');
    t.textContent = p.name;
    dot.appendChild(t);
    const jump = (): void => {
      if (p.id !== current) args.onJump(p.id);
    };
    dot.addEventListener('click', jump);
    dot.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        jump();
      }
    });
    svg.appendChild(dot);
    dotById.set(p.id, dot);
  }

  // "You are here" marker (on top) + current label.
  const here = document.createElementNS(NS, 'circle');
  here.setAttribute('class', 'viewer-fplan-here');
  here.setAttribute('r', '2.4');
  svg.appendChild(here);
  const label = document.createElementNS(NS, 'text');
  label.setAttribute('class', 'viewer-fplan-label');
  svg.appendChild(label);

  panel.appendChild(svg);
  args.hostEl.appendChild(panel);

  let yaw = 0;
  const drawCone = (): void => {
    const p = byId.get(current);
    if (!p) {
      cone.setAttribute('d', '');
      return;
    }
    const cx = sx(p.x);
    const cy = sy(p.y);
    here.setAttribute('cx', cx.toFixed(1));
    here.setAttribute('cy', cy.toFixed(1));
    // Map bearing: 0° = up (-y). Camera yaw rotates clockwise.
    const half = 27; // half cone angle
    const r = 17;
    const a0 = ((yaw + northOffset - half - 90) * Math.PI) / 180;
    const a1 = ((yaw + northOffset + half - 90) * Math.PI) / 180;
    const x0 = cx + r * Math.cos(a0);
    const y0 = cy + r * Math.sin(a0);
    const x1 = cx + r * Math.cos(a1);
    const y1 = cy + r * Math.sin(a1);
    cone.setAttribute(
      'd',
      `M ${cx.toFixed(1)} ${cy.toFixed(1)} L ${x0.toFixed(1)} ${y0.toFixed(1)} A ${r} ${r} 0 0 1 ${x1.toFixed(1)} ${y1.toFixed(1)} Z`,
    );
    // Label the current room above its dot, kept inside the box.
    label.textContent = p.name;
    label.setAttribute('x', cx.toFixed(1));
    label.setAttribute('y', (cy - 6).toFixed(1));
    label.setAttribute('text-anchor', cx > VB - 30 ? 'end' : cx < 30 ? 'start' : 'middle');
  };

  const paint = (): void => {
    for (const [id, dot] of dotById) {
      dot.classList.toggle('is-current', id === current);
      dot.classList.toggle('is-visited', visited.has(id) && id !== current);
      dot.setAttribute('r', id === current ? '4.4' : '3.4');
    }
    drawCone();
  };
  paint();

  return {
    setCurrent(id): void {
      current = id;
      visited.add(id);
      paint();
    },
    setCamera(yawDeg): void {
      yaw = yawDeg;
      drawCone();
    },
    dispose(): void {
      panel.remove();
    },
  };
};
