/**
 * POI projection math (S14).
 *
 * Each POI is anchored on a panorama by `{yaw, pitch}` in degrees. The viewer
 * paints a pin sprite at that point + opens a card when the pin is clicked.
 * This module is the pure-math layer:
 *
 *   - `sphericalToCartesian` maps yaw/pitch to a unit vector on the inverted
 *     sphere (matches the renderer's coordinate system, +Y up, +Z forward)
 *   - `projectPoiToScreen` projects a POI's anchor onto screen pixels given
 *     the camera state — used to position HTML overlay pins on top of the
 *     WebGL canvas (DOM-projection is cheaper than billboard sprites for the
 *     small N (<50) POIs per scene)
 *   - `isPoiInFrustum` tests whether the POI's vector points within the
 *     camera frustum (so we skip rendering offscreen pins)
 *   - `arrangePoiLabels` resolves label overlap when multiple POIs cluster
 *     within < clusterRadiusPx of each other (sorted by z-depth + zIndex)
 */

import type { CameraState } from './camera-controls';

export interface PoiAnchor {
  id: string;
  yaw: number;
  pitch: number;
  zIndex?: number;
  label?: string;
}

export interface CartesianVec3 {
  x: number;
  y: number;
  z: number;
}

const deg2rad = (d: number): number => (d * Math.PI) / 180;

/**
 * Yaw/pitch → unit vector on the renderer's inverted sphere.
 *
 * Conventions (matches `panorama-renderer.ts:applyCameraOrientation`):
 *   - yaw = 0, pitch = 0 → +Z (looking down the world's forward axis)
 *   - yaw +90° → +X (right)
 *   - pitch +90° → +Y (up)
 */
export const sphericalToCartesian = (yaw: number, pitch: number): CartesianVec3 => {
  const y = deg2rad(yaw);
  const p = deg2rad(pitch);
  return {
    x: Math.sin(y) * Math.cos(p),
    y: Math.sin(p),
    z: Math.cos(y) * Math.cos(p),
  };
};

export interface ProjectionViewport {
  widthPx: number;
  heightPx: number;
}

export interface ProjectedPoi {
  id: string;
  /** Screen x in CSS pixels, origin top-left. */
  screenX: number;
  /** Screen y. */
  screenY: number;
  /** Z-depth in camera space — used for ordering + frustum culling.
   * Negative when behind the camera (offscreen). */
  cameraZ: number;
  /** True when the anchor is in front of the camera AND within the FOV. */
  visible: boolean;
}

/**
 * Project a POI anchor to screen coordinates given the camera state. Uses
 * the same perspective projection Three.js does; pure-math so the viewer
 * doesn't need to read back from the WebGL pipeline.
 *
 * Returns `visible=false` when the anchor is behind the camera or outside
 * the horizontal FOV (vertical clipping is implicit via the projection).
 */
export const projectPoiToScreen = (
  anchor: PoiAnchor,
  camera: CameraState,
  viewport: ProjectionViewport,
): ProjectedPoi => {
  const target = sphericalToCartesian(anchor.yaw, anchor.pitch);
  const view = sphericalToCartesian(camera.yaw, camera.pitch);

  // Camera-space basis. We construct the inverse rotation from yaw/pitch.
  const cy = Math.cos(deg2rad(camera.yaw));
  const sy = Math.sin(deg2rad(camera.yaw));
  const cp = Math.cos(deg2rad(camera.pitch));
  const sp = Math.sin(deg2rad(camera.pitch));

  // Inverse of yaw-then-pitch rotation. Aligns the world such that the
  // camera's forward direction becomes the +Z axis:
  //   1) inverse yaw — rotate by -yaw around Y axis
  //   2) inverse pitch — rotate by +pitch around X axis (because
  //      `sphericalToCartesian` puts positive pitch on +Y, and the inverse
  //      transform that turns (sin(P), cos(P)) → (0, 1) is R_x(+P))
  const xWorldYaw = target.x * cy - target.z * sy;
  const yWorldYaw = target.y;
  const zWorldYaw = target.x * sy + target.z * cy;

  const xCam = xWorldYaw;
  const yCam = yWorldYaw * cp - zWorldYaw * sp;
  const zCam = yWorldYaw * sp + zWorldYaw * cp;

  const aspect = viewport.widthPx / Math.max(viewport.heightPx, 1);
  const halfFovRad = deg2rad(camera.fov / 2);
  const tanHalfFov = Math.tan(halfFovRad);

  const behindCamera = zCam <= 0;
  const ndcX = xCam / (zCam * tanHalfFov * aspect);
  const ndcY = yCam / (zCam * tanHalfFov);

  const screenX = (ndcX + 1) * 0.5 * viewport.widthPx;
  const screenY = (1 - (ndcY + 1) * 0.5) * viewport.heightPx;

  const insideHorizontal = !behindCamera && ndcX >= -1 && ndcX <= 1;
  const insideVertical = !behindCamera && ndcY >= -1 && ndcY <= 1;

  void view;
  return {
    id: anchor.id,
    screenX,
    screenY,
    cameraZ: zCam,
    visible: insideHorizontal && insideVertical && !behindCamera,
  };
};

/**
 * Label collision resolver. When N pins overlap inside a small radius,
 * pick the one with the highest zIndex (then nearest-z) as the "primary"
 * and mark the rest as `clusteredBehindId`. The viewer can then render
 * a cluster badge with a count + collapse the labels.
 */
export interface ClusterResult {
  primary: ProjectedPoi[];
  clusters: { primaryId: string; memberIds: string[]; count: number }[];
}

export const arrangePoiLabels = (
  projected: readonly ProjectedPoi[],
  anchors: readonly PoiAnchor[],
  clusterRadiusPx: number,
): ClusterResult => {
  const byId = new Map<string, PoiAnchor>();
  for (const a of anchors) byId.set(a.id, a);

  const visible = projected.filter((p) => p.visible);
  const claimed = new Set<string>();
  const clusters: ClusterResult['clusters'] = [];
  const primary: ProjectedPoi[] = [];

  // Sort by zIndex desc, then by cameraZ asc (nearest first).
  const ordered = [...visible].sort((a, b) => {
    const za = byId.get(a.id)?.zIndex ?? 0;
    const zb = byId.get(b.id)?.zIndex ?? 0;
    if (za !== zb) return zb - za;
    return a.cameraZ - b.cameraZ;
  });

  for (const p of ordered) {
    if (claimed.has(p.id)) continue;
    primary.push(p);
    claimed.add(p.id);

    const members: string[] = [];
    for (const q of ordered) {
      if (claimed.has(q.id)) continue;
      const dx = q.screenX - p.screenX;
      const dy = q.screenY - p.screenY;
      if (Math.hypot(dx, dy) <= clusterRadiusPx) {
        members.push(q.id);
        claimed.add(q.id);
      }
    }
    if (members.length > 0) {
      clusters.push({ primaryId: p.id, memberIds: members, count: members.length + 1 });
    }
  }

  return { primary, clusters };
};

/**
 * Tab-order index for keyboard navigation between POIs (FR-TVS-RND-007).
 * Iterates visible primaries left-to-right (then top-to-bottom) so screen
 * readers + sighted keyboard users get a predictable order.
 */
export const tabOrder = (projected: readonly ProjectedPoi[]): string[] =>
  [...projected]
    .filter((p) => p.visible)
    .sort((a, b) =>
      Math.abs(a.screenY - b.screenY) < 24 ? a.screenX - b.screenX : a.screenY - b.screenY,
    )
    .map((p) => p.id);
